document.querySelector('.menu-toggle').addEventListener('click',function(){const n=document.querySelector('#navigation');const open=n.classList.toggle('open');this.setAttribute('aria-expanded',String(open));});document.querySelectorAll('.nav-group').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.nav-group').forEach(x=>{if(x!==d)x.open=false})}));document.addEventListener('click',e=>{if(!e.target.closest('nav'))document.querySelectorAll('.nav-group').forEach(x=>x.open=false)});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.nav-group').forEach(x=>x.open=false)});document.querySelectorAll('.source-content form').forEach(f=>{f.removeAttribute('action');f.querySelectorAll('input[type=hidden],.recaptcha,.wpcf7-spinner,.wpcf7-response-output,.wpcf7-not-valid-tip').forEach(x=>x.remove());f.querySelectorAll('input[type=submit],button[type=submit]').forEach(x=>x.remove());const b=document.createElement('button');b.type='submit';b.className='button';b.textContent='Prepare email request';const note=document.createElement('p');note.className='form-note';note.textContent='Opens your email app with these details. Send the email to submit your request.';f.append(b,note);f.addEventListener('submit',event=>{event.preventDefault();const rows=[];for(const el of f.elements){if(!el.name||el.type==='submit'||((el.type==='radio'||el.type==='checkbox')&&!el.checked))continue;const label=el.closest('label')?.textContent.trim()||el.name;rows.push(label+': '+el.value)}location.href='mailto:dralizohery@gmail.com?subject='+encodeURIComponent(document.querySelector('h1').textContent+' request')+'&body='+encodeURIComponent(rows.join('\n'))})});function openTarget(){const el=document.getElementById(location.hash.slice(1));if(el?.tagName==='DETAILS')el.open=true}window.addEventListener('hashchange',openTarget);openTarget();document.querySelectorAll('img').forEach(i=>{i.addEventListener('error',()=>{const a=document.createElement('a');a.href=i.src;a.textContent=i.alt||'View original image ↗';a.className='broken-image';a.target='_blank';a.rel='noopener';i.replaceWith(a)})});const faq=document.querySelector('[data-faq]');if(faq){const search=document.createElement('input');search.type='search';search.placeholder='Search all questions…';search.className='faq-search';search.setAttribute('aria-label','Search frequently asked questions');faq.prepend(search);[...faq.querySelectorAll('h3')].forEach(h=>{const details=document.createElement('details');details.className='faq-item';const summary=document.createElement('summary');summary.innerHTML=h.innerHTML;const body=document.createElement('div');h.before(details);details.append(summary,body);let node=h.nextSibling;while(node&&!(node.nodeType===1&&/^(H[1-4]|HR)$/.test(node.tagName))){const next=node.nextSibling;body.append(node);node=next}h.remove()});search.addEventListener('input',()=>{const q=search.value.toLowerCase().trim();faq.querySelectorAll('.faq-item').forEach(d=>{const matched=d.textContent.toLowerCase().includes(q);d.hidden=!matched;d.open=!!q&&matched})})}